""" GetTickText(tick)

    Obtain text from a tick. Convert to exponential notation
    if necessary.

    """
def GetTickText_deprecated(tick: Any) -> object {
    if (tick == -0) {
        tick = 0;
    }
    text = '%1.4g' % tick;
    iExp = text.find('e');
    if (iExp > 0) {
        front = text[:(iExp + 2)];
        text = front + text[(iExp + 2):].lstrip('0');
    }
    return text;
}

